const fs = require("fs");
const path = require("path");
// parse watchbill
const wb = JSON.parse(fs.readFileSync("watchbill.json","utf8"));
// collect scenario names per feature file
const index = {};
for (const f of fs.readdirSync("features")) {
  if (!f.endsWith(".feature")) continue;
  const txt = fs.readFileSync(path.join("features",f),"utf8");
  const names = [];
  for (const line of txt.split("\n")) {
    const m = line.match(/^\s*(Scenario|Scenario Outline):\s*(.+?)\s*$/);
    if (m) names.push(m[2]);
  }
  index["features/"+f] = names;
}
let refs = 0, missing = [];
for (const [w, obj] of Object.entries(wb)) {
  for (const ref of obj.scenarios) {
    refs++;
    const [file, name] = ref.split(":");
    if (!index[file]) { missing.push(ref+"  (no such file)"); continue; }
    if (!index[file].includes(name)) { missing.push(ref+"  (scenario not found; have: "+JSON.stringify(index[file])+")"); }
  }
}
console.log("total scenario refs in watchbill:", refs);
console.log("total scenarios defined:", Object.values(index).reduce((a,b)=>a+b.length,0));
console.log("missing refs:", missing.length ? missing : "NONE");
'

